//! Compares every M0 operator with PyTorch, using `tests/golden/ops.safetensors` generated by
//! `tools/golden/gen_ops.py`. Each case in that file must have a handler here, and every tensor
//! of a case must be used.

mod common;

use std::sync::OnceLock;

use common::{Case, Golden};
use homura::{DType, Ellipsis, GeluApproximate, NewAxis, Tensor};

fn golden() -> &'static Golden {
    static G: OnceLock<Golden> = OnceLock::new();
    G.get_or_init(|| Golden::load("ops.safetensors"))
}

/// The part of a case name before the first `.`.
fn category(case: &str) -> &str {
    case.split('.').next().unwrap()
}

fn unary(name: &str, x: &Tensor) -> Option<Tensor> {
    Some(match name {
        "neg" => x.neg(),
        "abs" => x.abs(),
        "exp" => x.exp(),
        "log" => x.log(),
        "sqrt" => x.sqrt(),
        "rsqrt" => x.rsqrt(),
        "reciprocal" => x.reciprocal(),
        "sin" => x.sin(),
        "cos" => x.cos(),
        "tanh" => x.tanh(),
        "sigmoid" => x.sigmoid(),
        "relu" => x.relu(),
        "silu" => x.silu(),
        "gelu" => x.gelu(GeluApproximate::None),
        "gelu_tanh" => x.gelu(GeluApproximate::Tanh),
        "pow3" => x.pow(3),
        "clamp_float" => x.clamp(-1.5, 2.5),
        "clamp_int" => x.clamp(-1, 2),
        _ => return None,
    })
}

/// Runs one case and checks its outputs. Returns `false` if there is no handler for it.
fn run(c: &Case) -> bool {
    let name = c.name;
    let op = name.split_once('.').map_or("", |(_, op)| op);
    let x = || c.input("x");
    let (a, b) = (|| c.input("a"), || c.input("b"));
    let out = |t: Tensor| c.check("out", &t);
    let values_indices = |(v, i): (Tensor, Tensor)| {
        c.check("values", &v);
        c.check("indices", &i);
    };
    match category(name) {
        "unary" | "unary_wide" | "unary_special" | "unary_f16" | "unary_bf16" | "unary_f64"
        | "unary_int" => match unary(op, &x()) {
            Some(t) => out(t),
            None => return false,
        },
        "pow" => out(match op {
            "scalar2" => x().pow(2),
            "scalar3" => x().pow(3),
            "half" => x().pow(0.5),
            "neg" => x().pow(-1.5),
            _ => return false,
        }),
        "clamp" => out(match op {
            "both" => x().clamp(-0.5, 0.5),
            "min" => x().clamp_min(0.2),
            "max" => x().clamp_max(-0.1),
            "special" => x().clamp(-1.0, 1.0),
            "inverted" => x().clamp(0.5, -0.5),
            _ => return false,
        }),
        "logical_not" => out(x().logical_not()),
        "binary" | "binary_f16" | "binary_bf16" => out(match op {
            "add" => &a() + &b(),
            "sub" => &a() - &b(),
            "mul" => &a() * &b(),
            "div" => &a() / &b(),
            "maximum" => a().maximum(b()),
            "minimum" => a().minimum(b()),
            "pow" => a().pow(b()),
            "rsub" => 1.0 - &x(),
            "rdiv" => 2.0 / &x(),
            "add_scalar" => &x() + 2.5,
            "div_zero" => &a() / &b(),
            _ => return false,
        }),
        "compare" => out(match op {
            "gt" => a().greater(b()),
            "ge" => a().greater_equal(b()),
            "lt" => a().less(b()),
            "le" => a().less_equal(b()),
            "eq" => a().equal(b()),
            "ne" => a().not_equal(b()),
            "mixed_lt" => a().less(b()),
            "scalar_ge" => a().greater_equal(2.5),
            _ => return false,
        }),
        "logical" => out(match op {
            "and" => a().logical_and(b()),
            "or" => a().logical_or(b()),
            _ => return false,
        }),
        "promote" => out(match op {
            "i32_f16" | "u8_i8" | "f32_f64_zero_dim" | "i64_f64_zero_dim" | "i8_overflow"
            | "bool_add" => &a() + &b(),
            "bool_mul" | "i8_mul_overflow" => &a() * &b(),
            "i64_float_scalar" | "f16_float_scalar" => &a() * 2.5,
            "int_div" => &a() / &b(),
            "bool_int_scalar" => &a() + 1,
            "u8_minus_one" => &a() - 1,
            _ => return false,
        }),
        "where" => {
            let cond = c.input("cond");
            out(match op {
                "tensors" | "promote" => homura::where_(&cond, x(), c.input("y")),
                "scalar" => homura::where_(&cond, x(), 0.5),
                _ => return false,
            })
        }
        "masked_fill" => out(match op {
            "broadcast" => x().masked_fill(&c.input("mask"), -1e9),
            "int" => x().masked_fill(&c.input("mask"), 7),
            _ => return false,
        }),
        "reduce" | "ties" | "nan" | "var" | "std" | "bool" | "float" | "int" | "reduce_f16"
        | "reduce_bf16" => match op {
            "maximum" => out(a().maximum(b())),
            "minimum" => out(a().minimum(b())),
            "sum" => out(x().sum()),
            "sum_dims_keepdim" => out(x().sum_dim([0, 2], true)),
            "sum_last" => out(x().sum_dim(-1, false)),
            "sum_negative_dims" => out(x().sum_dim([-1, -3], false)),
            "sum_dim" if category(name) == "nan" || category(name) == "int" => {
                out(x().sum_dim(0, false))
            }
            "sum_dim" => out(x().sum_dim(-1, false)),
            "mean" => out(x().mean()),
            "mean_dim_keepdim" => out(x().mean_dim(1, true)),
            "prod" => out(x().prod()),
            "prod_dim" => out(x().prod_dim(1, false)),
            "max" => out(x().max()),
            "min" => out(x().min()),
            "max_dim" => values_indices(x().max_dim(1, false)),
            "min_dim" => values_indices(x().min_dim(0, false)),
            "min_dim_keepdim" => values_indices(x().min_dim(-1, true)),
            "argmax" => out(x().argmax()),
            "argmax_dim" => out(x().argmax_dim(1, false)),
            "argmin_dim" if category(name) == "ties" => out(x().argmin_dim(1, false)),
            "argmin_dim" => out(x().argmin_dim(2, false)),
            "default" => out(x().var(1)),
            "dim_c0_keepdim" => out(x().var_dim(1, 0, true)),
            "single" => out(x().var(1)),
            "dims" => out(x().std_dim([0, 2], 1, false)),
            "dim_c2" => out(x().std_dim(2, 2, false)),
            "var_dim" => out(x().var_dim(1, 1, false)),
            "all" => out(x().all()),
            "any" => out(x().any()),
            "any_dim" => out(x().any_dim(1, false)),
            "all_dim_keepdim" => out(x().all_dim(0, true)),
            _ => return false,
        },
        "matmul" => out(match op {
            "transposed" => a().transpose(0, 1).matmul(&b().transpose(0, 1)),
            _ => a().matmul(&b()),
        }),
        "softmax" => out(match op {
            "last" | "f16" | "inf" => x().softmax(-1),
            "first" => x().softmax(0),
            _ => return false,
        }),
        "log_softmax" => out(match op {
            "mid" => x().log_softmax(1),
            "inf" => x().log_softmax(-1),
            _ => return false,
        }),
        "addmm" => {
            let (input, m1, m2) = (c.input("input"), c.input("m1"), c.input("m2"));
            out(match op {
                "full" => input.addmm(&m1, &m2, 0.5, 2.0),
                "bias" => input.addmm(&m1, &m2, 1, 1),
                "beta0" => input.addmm(&m1, &m2, 0, 1),
                _ => return false,
            })
        }
        "addmv" => out(c
            .input("input")
            .addmv(&c.input("mat"), &c.input("vec"), 2, 0.5)),
        "addr" => out(c.input("input").addr(&c.input("v1"), &c.input("v2"), 1, -1)),
        "baddbmm" => out(c
            .input("input")
            .baddbmm(&c.input("b1"), &c.input("b2"), 0.5, 1.5)),
        "addbmm" => out(c
            .input("input")
            .addbmm(&c.input("b1"), &c.input("b2"), 1, 1)),
        "addcmul" => out(c
            .input("input")
            .addcmul(&c.input("t1"), &c.input("t2"), 0.5)),
        "addcdiv" => out(c.input("input").addcdiv(&c.input("t1"), &c.input("t2"), -2)),
        "lerp" => {
            let (start, end) = (c.input("start"), c.input("end"));
            out(match op {
                "low" => start.lerp(&end, 0.3),
                "high" => start.lerp(&end, 0.7),
                "tensor" => start.lerp(&end, c.input("weight")),
                _ => return false,
            })
        }
        "concat" => out(homura::concat(&[a(), b(), c.input("c")], 1)),
        "stack" => out(match op {
            "last" => homura::stack(&[a(), b()], -1),
            "first" => homura::stack(&[a(), b()], 0),
            _ => return false,
        }),
        "split" | "split_with_sizes" | "chunk" => {
            let parts = match name {
                "split.size3" => x().split(3, 1),
                "split_with_sizes" => x().split_with_sizes(&[2, 4, 1], 1),
                "chunk.three" => golden().get("split.size3/x").chunk(3, 1),
                _ => return false,
            };
            assert_eq!(
                parts.len(),
                c.golden
                    .names(name)
                    .iter()
                    .filter(|n| n.starts_with("out"))
                    .count()
            );
            for (k, p) in parts.iter().enumerate() {
                c.check(&format!("out{k}"), p);
            }
        }
        "triu" => out(match op {
            "batched" => x().triu(1),
            "square" => x().triu(0),
            _ => return false,
        }),
        "tril" => out(x().tril(-1)),
        "repeat" => out(x().repeat([2, 1, 3])),
        "flip" => out(x().flip([0, 2])),
        "index" => out(match op {
            "slice" => x().index((.., 1..3)),
            "ellipsis_last" => x().index((Ellipsis, -1)),
            "newaxis" => x().index((0, NewAxis)),
            "step" => x().index((.., (0..).step_by(2))),
            "negative_start" => x().index(-2..),
            "mixed" => x().index((1.., -3..-1, (0..).step_by(3))),
            "clamped" => x().index((.., -10..10, 2..100)),
            "tensor" => x().index(c.input("idx")),
            "tensor_2d" => x().index((.., &c.input("idx"))),
            "tensor_after_select" => x().index((1, .., &c.input("idx"))),
            _ => return false,
        }),
        "index_select" => out(x().index_select(1, &c.input("idx"))),
        "view" => out(match op {
            "permute" => x().permute([2, 0, 1]),
            "transpose" => x().transpose(0, 2),
            "narrow" => x().narrow(1, 1, 2),
            "select" => x().select(2, -1),
            "flatten" => x().flatten(1, 2),
            "reshape_copy" => x().transpose(0, 1).reshape([4, 15]),
            "expand" => x().expand([-1, 4, 5]),
            _ => return false,
        }),
        "create" => out(match op {
            "arange_int" => homura::arange(10),
            "arange_float_step" => homura::arange_step(0, 1, 0.1),
            "arange_negative_step" => homura::arange_step(5, 0, -2),
            "arange_float_end" => homura::arange_step(0.0, 1.0, 0.3),
            "linspace" => homura::linspace(0.0, 1.0, 7),
            "linspace_neg" => homura::linspace(-3.0, 10.0, 6),
            "linspace_one" => homura::linspace(2.0, 5.0, 1),
            "linspace_empty" => homura::linspace(2.0, 5.0, 0),
            "eye" => homura::eye(3),
            "full_int" => homura::full([2, 3], 7),
            "full_float" => homura::full([2], 2.5),
            _ => return false,
        }),
        "cast" => out(match op {
            "f32_i32" => x().to(DType::I32),
            "f32_i64" => x().to(DType::I64),
            "f32_bool" => x().to(DType::Bool),
            "f32_f16" | "f16_rounding" => x().to(DType::F16),
            "f32_bf16" | "bf16_rounding" => x().to(DType::BF16),
            "i64_f32" | "bool_f32" | "f16_f32" => x().to(DType::F32),
            _ => return false,
        }),
        "sum_to_size" => out(x().sum_to_size(match op {
            "leading" => vec![3, 4],
            "ones" => vec![2, 1, 4],
            "mixed" => vec![3, 1],
            "scalar" => vec![],
            "same" => vec![2, 3, 4],
            "int" => vec![1, 5],
            "empty" => vec![1, 3],
            "f16" => vec![4],
            _ => return false,
        })),
        _ => return false,
    }
    c.assert_all_used();
    true
}

fn run_categories(categories: &[&str]) {
    let g = golden();
    let mut count = 0;
    for case in g.cases() {
        if !categories.contains(&category(&case)) {
            continue;
        }
        let c = Case::new(g, &case);
        assert!(run(&c), "no handler for golden case {case:?}");
        count += 1;
    }
    assert!(count > 0, "no golden cases in {categories:?}");
}

const UNARY: &[&str] = &[
    "unary",
    "unary_wide",
    "unary_special",
    "unary_f16",
    "unary_bf16",
    "unary_f64",
    "unary_int",
    "pow",
    "clamp",
    "logical_not",
];
const BINARY: &[&str] = &[
    "binary",
    "binary_f16",
    "binary_bf16",
    "compare",
    "logical",
    "promote",
    "where",
    "masked_fill",
];
const REDUCE: &[&str] = &[
    "reduce",
    "ties",
    "nan",
    "var",
    "std",
    "bool",
    "float",
    "int",
    "reduce_f16",
    "reduce_bf16",
    "sum_to_size",
];
const LINALG: &[&str] = &[
    "matmul",
    "softmax",
    "log_softmax",
    "addmm",
    "addmv",
    "addr",
    "baddbmm",
    "addbmm",
    "addcmul",
    "addcdiv",
    "lerp",
];
const SHAPE: &[&str] = &[
    "concat",
    "stack",
    "split",
    "split_with_sizes",
    "chunk",
    "triu",
    "tril",
    "repeat",
    "flip",
    "index",
    "index_select",
    "view",
];
const CREATE: &[&str] = &["create", "cast"];

#[test]
fn unary_ops() {
    run_categories(UNARY);
}

#[test]
fn binary_ops() {
    run_categories(BINARY);
}

#[test]
fn reductions() {
    run_categories(REDUCE);
}

#[test]
fn matmul_and_composite_ops() {
    run_categories(LINALG);
}

#[test]
fn shape_view_and_index_ops() {
    run_categories(SHAPE);
}

#[test]
fn creation_and_casting() {
    run_categories(CREATE);
}

#[test]
fn every_golden_case_has_a_test() {
    let known: Vec<&str> = [UNARY, BINARY, REDUCE, LINALG, SHAPE, CREATE].concat();
    for case in golden().cases() {
        assert!(
            known.contains(&category(&case)),
            "golden case {case:?} is not covered by any test"
        );
    }
}
